<script>
(function(){
var seed={id:'root',tag:'main',label:'Page',text:'',attrs:{},styles:{},children:[{id:'hero',tag:'section',label:'Hero section',text:'',attrs:{},styles:{background:'#0f172a',color:'#ffffff'},children:[{id:'title',tag:'h1',label:'Headline',text:'Build your next workflow.',attrs:{},styles:{color:'#ffffff'}},{id:'sub',tag:'p',label:'Supporting copy',text:'A focused operating system for service businesses that want every request to become a completed, paid, and repeatable workflow.',attrs:{},styles:{color:'#cbd5e1'}},{id:'cta',tag:'a',label:'Primary CTA',text:'Build my first workflow',attrs:{href:'#start'},styles:{background:'#60a5fa',color:'#0f172a'}}]},{id:'content',tag:'section',label:'Feature section',text:'',attrs:{},styles:{background:'#ffffff',color:'#0f172a'},children:[{id:'content-title',tag:'h2',label:'Section headline',text:'One calm operating loop.',attrs:{},styles:{}},{id:'content-copy',tag:'p',label:'Section copy',text:'Capture demand, schedule service, collect payment, and keep customers informed from one tenant-scoped workspace.',attrs:{},styles:{}},{id:'tiles',tag:'div',label:'Feature grid',text:'',attrs:{},styles:{display:'grid',gap:'12px'},children:[{id:'tile1',tag:'article',label:'Feature card 1',text:'Request to revenue',attrs:{},styles:{border:'1px solid #e2e8f0',padding:'16px'}},{id:'tile2',tag:'article',label:'Feature card 2',text:'Exception intelligence',attrs:{},styles:{border:'1px solid #e2e8f0',padding:'16px'}},{id:'tile3',tag:'article',label:'Feature card 3',text:'Governed AI actions',attrs:{},styles:{border:'1px solid #e2e8f0',padding:'16px'}}]}]},{id:'footer',tag:'footer',label:'Footer',text:'',attrs:{},styles:{background:'#0f172a',color:'#cbd5e1'},children:[{id:'footer-text',tag:'span',label:'Footer text',text:'Slate · Built for better operations',attrs:{},styles:{}}]}]};
var key='slate-visual-editor-mvp-v1',seoDefaults=<?= json_encode($seoSettings, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,doc,selected='title',history=[],future=[];try{doc=JSON.parse(localStorage.getItem(key)||'null')}catch(e){}if(!doc)doc=seed;
function clone(v){return JSON.parse(JSON.stringify(v))}function find(n,id){if(n.id===id)return n;for(var i=0;i<n.children.length;i++){var f=find(n.children[i],id);if(f)return f}return null}function count(n){return 1+n.children.reduce(function(a,c){return a+count(c)},0)}
function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}function style(n){var s='';Object.keys(n.styles||{}).forEach(function(k){if(n.styles[k])s+=k.replace(/[A-Z]/g,function(m){return '-'+m.toLowerCase()})+':'+esc(n.styles[k])+';'});return s}
function html(n){var inner='';if(n.children&&n.children.length)inner=n.children.map(html).join('');else if(n.text)inner=esc(n.text);var attrs=Object.keys(n.attrs||{}).map(function(k){return ' '+esc(k)+'="'+esc(n.attrs[k])+'"'}).join('');var tag=n.tag==='main'?'div':n.tag;var cls='ve-node '+(n.id===selected?'selected':'');var result='<'+tag+' class="'+cls+'" data-node="'+n.id+'" data-label="'+esc(n.label)+'" style="'+style(n)+'"'+attrs+'>'+inner+'</'+tag+'>';return result}
function render(){document.getElementById('ve-page').innerHTML='<div class="ve-node '+(selected==='root'?'selected':'')+'" data-node="root" data-label="Page">'+doc.children.map(html).join('')+'</div>';document.getElementById('ve-node-count').textContent=count(doc)+' nodes';document.querySelectorAll('[data-node]').forEach(function(el){el.addEventListener('click',function(e){e.stopPropagation();selected=this.dataset.node;render();inspector()})});inspector();layers()}
function layers(){var out='';function row(n,depth){out+='<button class="ve-layer '+(n.id===selected?'active':'')+'" data-layer="'+n.id+'" style="padding-left:'+(9+depth*14)+'px"><span class="ve-chevron">'+(n.children.length?'▾':'·')+'</span><span class="ve-tag">'+esc(n.tag)+'</span><span>'+esc(n.label)+'</span></button>';n.children.forEach(function(c){row(c,depth+1)})}row(doc,0);document.getElementById('ve-layers').innerHTML=out;document.querySelectorAll('[data-layer]').forEach(function(b){b.addEventListener('click',function(){selected=this.dataset.layer;render();})})}
function inspector(){var n=find(doc,selected),box=document.getElementById('ve-inspector');if(!n){box.innerHTML='<div class="ve-empty">Select a layer or element.</div>';return}var canText=n.tag!=='div'&&n.tag!=='main'&&n.tag!=='section'&&n.tag!=='article'&&n.tag!=='footer';box.innerHTML='<div class="ve-field"><label>Element</label><input value="'+esc(n.tag)+'" disabled></div><div class="ve-field"><label>Label</label><input id="ve-label" value="'+esc(n.label)+'"></div>'+(canText?'<div class="ve-field"><label>Text content</label><textarea id="ve-text">'+esc(n.text)+'</textarea></div>':'')+'<div class="ve-field"><label>CSS class</label><input id="ve-class" value="'+esc(n.attrs.class||'')+'" placeholder="component-class"></div><div class="ve-divider"></div><div class="ve-field"><label>Styles</label><div class="ve-style-grid"><input id="ve-color" placeholder="color" value="'+esc(n.styles.color||'')+'"><input id="ve-bg" placeholder="background" value="'+esc(n.styles.background||'')+'"><input id="ve-padding" placeholder="padding" value="'+esc(n.styles.padding||'')+'"><input id="ve-gap" placeholder="gap" value="'+esc(n.styles.gap||'')+'"></div></div><button class="ve-btn" id="ve-duplicate" type="button">Duplicate</button> <button class="ve-btn" id="ve-delete" type="button">Delete</button>';
['ve-label','ve-text','ve-class','ve-color','ve-bg','ve-padding','ve-gap'].forEach(function(id){var el=document.getElementById(id);if(el)el.addEventListener('input',function(){history.push(clone(doc));future=[];if(id==='ve-label')n.label=this.value;if(id==='ve-text')n.text=this.value;if(id==='ve-class')n.attrs.class=this.value;if(id==='ve-color')n.styles.color=this.value;if(id==='ve-bg')n.styles.background=this.value;if(id==='ve-padding')n.styles.padding=this.value;if(id==='ve-gap')n.styles.gap=this.value;save();render()})});document.getElementById('ve-duplicate').onclick=function(){var parent=parentOf(doc,n.id);if(!parent)return;history.push(clone(doc));var copy=clone(n);copy.id=copy.id+'_copy_'+Date.now();copy.label+=' copy';parent.children.splice(parent.children.indexOf(n)+1,0,copy);selected=copy.id;save();render()};document.getElementById('ve-delete').onclick=function(){if(n.id==='root')return;var parent=parentOf(doc,n.id);if(!parent)return;history.push(clone(doc));parent.children=parent.children.filter(function(c){return c.id!==n.id});selected=parent.id;save();render()}}
function parentOf(n,id){for(var i=0;i<n.children.length;i++){if(n.children[i].id===id)return n;if(parentOf(n.children[i],id))return parentOf(n.children[i],id)}return null}function save(){localStorage.setItem(key,JSON.stringify(doc));var s=document.getElementById('ve-save-state');s.textContent='Saved locally';s.className='ve-status saved'}
document.querySelectorAll('[data-device]').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('[data-device]').forEach(function(x){x.classList.remove('active')});this.classList.add('active');var page=document.getElementById('ve-page');page.className='ve-page '+(this.dataset.device==='desktop'?'':this.dataset.device)})});document.getElementById('ve-undo').onclick=function(){if(!history.length)return;future.push(clone(doc));doc=history.pop();save();render()};document.getElementById('ve-redo').onclick=function(){if(!future.length)return;history.push(clone(doc));doc=future.pop();save();render()};document.getElementById('ve-preview').onclick=function(){alert('Preview mode is ready for the staged renderer in the next publish batch. Current draft is stored locally.')};document.getElementById('ve-publish').onclick=function(){alert('Validation gate: add database-backed page persistence, SEO checks, accessibility checks, and server-side publish before enabling production publish.')};render();
})();
</script>
